  15 => 
  array (
    'id' => 'comision-medica-016',
    'categoria' => 'Comisión Médica',
    'pregunta' => '¿Qué es el dictamen de la Comisión Médica?',
    'respuesta_corta' => 'Es la resolución oficial donde determinan tu porcentaje de incapacidad y los derechos que te corresponden.',
    'respuesta_completa' => '<div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">El dictamen de la Comisión Médica es la resolución oficial donde se fija tu porcentaje de incapacidad y la indemnización que te corresponde.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📄 Contenido: Establece el porcentaje de incapacidad que te asignan según la evaluación médica realizada.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">💰 Derechos: Determina la indemnización que te corresponde según la fórmula del art. 14 de la Ley 24.557.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📨 Notificación: Tienen que notificarte formalmente del dictamen para que puedas ejercer tu derecho a apelar.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">⚖️ Apelación: Si no estás conforme, podés apelar ante la Comisión Médica Central dentro de los 5 días hábiles.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">🔒 Vinculante: El dictamen es vinculante para las partes, salvo que sea apelado dentro del plazo.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">💳 Efectos: Una vez firme, y homologado el acuerdo o la resolución, la ART tiene que depositarte la indemnización dentro de los 5 días hábiles siguientes a la notificación de la homologación.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">💡 Consejo práctico: Revisá cuidadosamente el dictamen y verificá que el porcentaje respete el baremo vigente. Si no es así, apelá dentro del plazo.</div>',
    'definiciones_relacionadas' => 
    array (
    ),
    'lesiones_relacionadas' => 
    array (
    ),
    'artículos_relacionados' => 
    array (
